import React from 'react';
import {
  ComposableMap,
  Geographies,
  Geography
} from 'react-simple-maps';
import MapContainer from '../../shared/MapContainer';
import DiagonalPatternBackground from './DiagonalPatternBackground';
import FourColorMapColoring from './FourColorMapColoring';

// URL to US states data
const geoUrl = "https://cdn.jsdelivr.net/npm/us-atlas@3/states-10m.json";

const Map: React.FC = () => {
  return (
    <MapContainer filename="usa-geographic.svg">
      <ComposableMap
        projection="geoAlbers"
        projectionConfig={{
          // Using more conservative scale to ensure visibility
          scale: 600,
          // Centering on continental US
          rotate: [-96, 0, 0],
          // Standard parallels for US Albers projection
          parallels: [29.5, 45.5],
          // Slight northward shift to center vertically
          center: [0, 40]
        }}
        width={800}
        height={500}
      >
        {/* Background pattern */}
        <DiagonalPatternBackground 
          backgroundColor="#f8f9fa" 
          lineColor="#e9ecef" 
          lineWidth={2}
          lineSpacing={6}
          direction="left"
        />
        
        {/* Main map */}
        <Geographies geography={geoUrl}>
          {({ geographies }) => (
            <FourColorMapColoring 
              geographies={geographies}
              // Excluding Hawaii to show it in inset
              geographies={geographies.filter(geo => 
                geo.properties.name !== "Hawaii"
              )}
            />
          )}
        </Geographies>
        
        {/* Hawaii inset - positioned on LEFT side as traditionally done */}
        <g transform="translate(20, 400) scale(0.5)">
          {/* Inset border and background */}
          <rect 
            x="0" 
            y="0" 
            width="150" 
            height="100" 
            fill="#f8f9fa" 
            stroke="#ddd" 
            strokeWidth="1"
          />
          
          {/* Label */}
          <text 
            x="75" 
            y="15" 
            textAnchor="middle" 
            fontSize="12"
            fill="#333"
          >
            Hawaii
          </text>
          
          {/* Small map projection specifically for Hawaii */}
          <g transform="translate(75, 60) scale(0.15)">
            <Geographies geography={geoUrl}>
              {({ geographies }) => 
                geographies
                  .filter(geo => geo.properties.name === "Hawaii")
                  .map(geo => (
                    <Geography
                      key={geo.rsmKey}
                      geography={geo}
                      fill="#D6D6DA"
                      stroke="#FFFFFF"
                      strokeWidth={0.5}
                    />
                  ))
              }
            </Geographies>
          </g>
        </g>
      </ComposableMap>
    </MapContainer>
  );
};

export default Map;`}),e(n,{children:"This should produce a visible map with:"}),t(n,{children:[e(h,{ordered:!0}),e(o,{children:"Alaska in its true position using the Albers projection"}),e(o,{children:"Hawaii shown in an inset on the LEFT side"}),e(o,{children:"All elements properly structured for Illustrator export"}),e(o,{children:"Conservative scale and rotation parameters to ensure visibility"})]}),e(n,{children:"If there are still issues, we may need to fall back to a simpler approach using the built-in geoAlbersUsa projection, which is guaranteed to work but doesn't show Alaska in its true position."})]}),t(s,{at:"2025-03-26T19:01:28.254301Z",children:[e(i,{children:"711c7aa1-0eb8-4b0a-972a-7db53b0610ed"}),e(l,{children:"[Doug](/dougs-story/)"}),e(n,{children:"Doug: It doesn't fix it. Why do you think you know how to fix it? Maybe you can think to run an experiment to fix this with tiny code changes so you can learn? I need to see an approach to coding where you learn"}),e(x,{children:"Uploaded “image.png”, whose content the export does not carry"})]}),t(s,{at:"2025-03-26T19:01:49.049111Z",children:[e(i,{children:"1a2becba-9f53-4320-9633-8ff2128e43ce"}),e(l,{children:"[Claude](/dougs-claude/)"}),e(n,{children:"I see I've been approaching this problem incorrectly by assuming I know how to fix it without proper experimentation. You're right that a methodical learning approach would be more effective."}),e(n,{children:"Let me try a much simpler experiment-based approach to fix the blank map issue:"}),t(n,{children:[e(h,{ordered:!0}),e(o,{children:"First, let's confirm what we know works - the standard AlbersUSA projection:"})]}),e(c,{language:"tsx",children:`// Guaranteed working version for comparison
